+        messageField.setInvalid(false);
+    }
+
+    private static void markInvalid(HasValidationProperties field, String errorMessage) {
+        field.setErrorMessage(errorMessage);
+        field.setInvalid(true);
+    }
+
+    private void refreshMessages() {
+        messageGrid.setItems(messageStore.getMessages());
+    }
+
+    private boolean hasUnsavedChanges() {
+        return !nameField.getValue().isEmpty()
+                || !emailField.getValue().isEmpty()
+                || !phoneField.getValue().isEmpty()
+                || !messageField.getValue().isEmpty();
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (!hasUnsavedChanges()) {
+            return;
+        }
+
+        if (pendingNavigation != null) {
+            return;
+        }
+
+        pendingNavigation = event.postpone();
+        showDiscardDialog();
+    }
+
+    private void showDiscardDialog() {
+        discardDialog = new Dialog();
+        discardDialog.setHeaderTitle("Discard changes?");
+        discardDialog.setCloseOnEsc(false);
+        discardDialog.setCloseOnOutsideClick(false);
+        discardDialog.add(new Paragraph("You have unsent changes. Do you want to discard them?"));
+
+        Button keepEditing = new Button("Keep editing", event -> {
+            discardDialog.close();
+            BeforeLeaveEvent.ContinueNavigationAction action = pendingNavigation;
+            pendingNavigation = null;
+            if (action != null) {
+                action.cancel();
+            }
+        });
+        Button discard = new Button("Discard", event -> {
+            discardDialog.close();
+            BeforeLeaveEvent.ContinueNavigationAction action = pendingNavigation;
+            pendingNavigation = null;
+            if (action != null) {
+                action.proceed();
+            }
+        });
+        discardDialog.getFooter().add(new HorizontalLayout(keepEditing, discard));
+        discardDialog.open();
+    }
+}
