+
+        test($(TextField.class).withLabel("Name").single()).setValue("Ada");
+        test($(EmailField.class).withLabel("Email").single()).setValue("ada@example.com");
+        test($(TextField.class).withLabel("Phone").single()).setValue("555");
+        test($(TextArea.class).withLabel("Message").single()).setValue("Hello");
+
+        fireShortcut(Key.ENTER);
+
+        assertEquals("", $(TextField.class).withLabel("Name").single().getValue());
+        assertFalse($(Button.class).withText("Send").single().isEnabled());
+        assertTrue($(Notification.class).all().stream()
+                .anyMatch(notification -> test(notification).getText().contains("Message sent")));
+        Grid<ContactMessage> grid = $(Grid.class).single();
+        assertEquals(1, test(grid).size());
+        assertEquals("Ada", test(grid).getRow(0).name());
+        assertEquals("Hello", test(grid).getRow(0).message());
+
+        test($(TextField.class).withLabel("Name").single()).setValue("Grace");
+        assertTrue($(Button.class).withText("Send").single().isEnabled());
